import sys
from collections import deque

def main():
    data = sys.stdin.read().split()
    r, c = int(data[0]), int(data[1])
    g = data[2:2 + r]
    dist = [[-1] * c for _ in range(r)]
    q = deque()
    for i in range(r):
        for j in range(c):
            if g[i][j] == 'G':
                dist[i][j] = 0
                q.append((i, j))
    while q:
        i, j = q.popleft()
        d = dist[i][j] + 1
        for a, b in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
            if 0 <= a < r and 0 <= b < c and g[a][b] == '.' and dist[a][b] == -1:
                dist[a][b] = d
                q.append((a, b))
    print('\n'.join(' '.join(map(str, row)) for row in dist))

