import sys
from collections import deque

data = sys.stdin.read().split()
r, c = int(data[0]), int(data[1])
g = data[2:2 + r]

def bfs_from(si, sj):
    seen = {(si, sj): 0}
    q = deque([(si, sj)])
    while q:
        i, j = q.popleft()
        if g[i][j] == 'G':
            return seen[(i, j)]
        for a, b in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
            if 0 <= a < r and 0 <= b < c and g[a][b] != '#' and (a, b) not in seen:
                seen[(a, b)] = seen[(i, j)] + 1
                q.append((a, b))
    return -1

rows = []
for i in range(r):
    rows.append(' '.join(str(-1 if g[i][j] == '#' else bfs_from(i, j)) for j in range(c)))
print('\n'.join(rows))

